#!/usr/bin/env node
/**
 * Verifies the self-contained preview page the CLI emits actually renders.
 *
 * Why this exists
 * ---------------
 * The editor's reference pane runs inside an OS webview, and a webview cannot
 * run in headless CI — it needs a real platform web engine. But the *page* the
 * pane displays is just HTML, and that can be checked anywhere Playwright runs.
 * So the page is generated by `merpeeps preview` and exercised here, which means
 * CI covers the reference-render path on machines that could never host the
 * webview itself.
 *
 * What it proves, in order of importance:
 *   1. The page renders an SVG at all, offline, with no network access.
 *   2. Loading merpeeps-mermaid-layout from blob URLs works — that is the
 *      published package's real source, so this is end-to-end proof the npm
 *      artefact functions in a browser.
 *   3. Stored positions are honoured in the Merpeeps page and absent in the plain
 *      one, which is the whole claim the format makes.
 *
 * Run:  node oracle/preview-page-test.mjs
 */
import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

const repo = resolve(import.meta.dirname, '..');
const cli = join(repo, 'src', 'Merpeeps.Cli', 'bin', 'Release', 'net10.0', 'merpeeps.dll');
// Reads the gate's own fixture, not docs/styled-sample.mmd. That file is what
// the editor opens by default, so anyone trying the app out edits it — which
// silently changed the diagram under three gates and failed them on code that
// was fine. A fixture has to be something no one is invited to edit.
const sample = join(repo, 'oracle', 'fixtures', 'styled.mmd');

if (!existsSync(cli)) {
  console.error(`FAIL: CLI not built at ${cli}\n      run: dotnet build -c Release`);
  process.exit(1);
}

const work = mkdtempSync(join(tmpdir(), 'merpeeps-preview-'));
const fail = [];
const note = (ok, msg) => {
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${msg}`);
  if (!ok) fail.push(msg);
};

function emit(name, extra) {
  const out = join(work, name);
  execFileSync('dotnet', [cli, 'preview', sample, ...extra, '--out', out], {
    stdio: ['ignore', 'ignore', 'pipe'],
  });
  return out;
}

const pages = {
  merpeeps: emit('merpeeps.html', []),
  plain: emit('plain.html', ['--plain']),
};

const { chromium } = await import('playwright');
const browser = await chromium
  .launch(process.env.MERPEEPS_ORACLE_CHANNEL === 'bundled' ? {} : { channel: 'chrome' })
  .catch(() => chromium.launch());

const results = {};

for (const [label, file] of Object.entries(pages)) {
  const page = await browser.newPage({ viewport: { width: 1200, height: 900 } });

  const pageErrors = [];
  page.on('pageerror', (e) => pageErrors.push(e.message));

  // Refuse every network request. The page claims to be self-contained; this
  // turns that claim into something the test can fail on.
  const network = [];
  await page.route('**', (route) => {
    const url = route.request().url();
    if (url.startsWith('file:') || url.startsWith('blob:') || url.startsWith('data:')) {
      return route.continue();
    }
    network.push(url);
    return route.abort();
  });

  await page.goto(`file://${file.replace(/\\/g, '/')}`, { waitUntil: 'load' });
  await page.waitForFunction(() => window.merpeepsRendered === true, { timeout: 30_000 })
    .catch(() => {});

  const shown = await page.evaluate(() => {
    const svg = document.querySelector('#stage svg');
    const err = document.getElementById('err');
    const nodes = svg ? svg.querySelectorAll('.node, .nodes > g') : [];
    const boxes = [...nodes].map((n) => {
      const b = n.getBoundingClientRect();
      return { x: Math.round(b.x), y: Math.round(b.y) };
    });
    return {
      hasSvg: !!svg,
      nodeCount: nodes.length,
      error: err && err.style.display !== 'none' ? err.textContent : null,
      boxes,
      fills: svg
        ? [...svg.querySelectorAll('g.node')]
            .map((g) => {
              // The plugin paints through CSS, not the fill attribute, so read
              // what the browser actually resolved. Reading [fill] here found
              // nothing and looked like a product bug; it was a measurement bug.
              const shape = g.querySelector('rect, circle, ellipse, polygon, path');
              return shape ? getComputedStyle(shape).fill : null;
            })
            .filter(Boolean)
        : [],
    };
  });

  results[label] = shown;

  note(!shown.error, `${label}: page reported no error` + (shown.error ? ` — ${shown.error.slice(0, 300)}` : ''));
  note(pageErrors.length === 0, `${label}: no uncaught page errors` + (pageErrors.length ? ` — ${pageErrors[0]}` : ''));
  note(network.length === 0, `${label}: made no network requests` + (network.length ? ` — tried ${network[0]}` : ''));
  note(shown.hasSvg, `${label}: rendered an <svg>`);
  note(shown.nodeCount >= 6, `${label}: drew all 6 nodes (saw ${shown.nodeCount})`);

  await page.close();
}

// The load-bearing claim: the Merpeeps page places nodes where the file says, the
// plain page lets mermaid lay them out. If those agree, the plugin did nothing.
if (results.merpeeps?.boxes?.length && results.plain?.boxes?.length) {
  const same = JSON.stringify(results.merpeeps.boxes) === JSON.stringify(results.plain.boxes);
  note(!same, 'stored positions changed the layout (merpeeps page differs from plain)');

  const merpeepsFills = new Set(results.merpeeps.fills);
  const plainFills = new Set(results.plain.fills);
  const extra = [...merpeepsFills].filter((f) => !plainFills.has(f));
  note(extra.length > 0, `merpeeps page applied stored fills (${extra.length} colours the plain page lacks)`);
} else {
  note(false, 'could not compare layouts — one page produced no node boxes');
}

await browser.close();
rmSync(work, { recursive: true, force: true });

console.log('');
if (fail.length) {
  console.log(`PREVIEW PAGE TEST FAILED — ${fail.length} check(s)`);
  process.exit(1);
}
console.log('PREVIEW PAGE VERIFIED — self-contained, offline, plugin applied from published source');
